import{_ as s,o as t,c as e,ag as n}from"./chunks/framework.-Wrcbzkw.js";const u=JSON.parse('{"title":"If-I-Held - 如果当时没有卖","description":"","frontmatter":{},"headers":[],"relativePath":"project/If-I-Held.md","filePath":"project/If-I-Held.md","lastUpdated":1781418787000}'),i={name:"project/If-I-Held.md"};function l(p,a,d,r,h,o){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="if-i-held-如果当时没有卖" tabindex="-1">If-I-Held - 如果当时没有卖 <a class="header-anchor" href="#if-i-held-如果当时没有卖" aria-label="Permalink to &quot;If-I-Held - 如果当时没有卖&quot;">​</a></h1><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p><a href="https://github.com/xxxeuniii/If-I-Held" target="_blank" rel="noreferrer">If-I-Held</a> 是一个轻量、有趣的股票复盘工具。用户输入曾经卖出的股票、数量和价格，应用会获取当前行情，并计算“如果当时没有卖出，现在会怎样”。</p><p>与传统收益计算器不同，项目不仅展示收益差额和收益率，还会生成带有情绪色彩的复盘文案，并将机会成本换算成奶茶、电影票、iPhone、PS5 或旅行天数等更直观的生活消费。</p><p><strong>在线体验</strong>：<a href="https://if-i-held.vercel.app/" target="_blank" rel="noreferrer">https://if-i-held.vercel.app/</a></p><p><strong>核心流程</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入股票代码、卖出数量与卖出价格</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>从东方财富获取当前行情</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>计算持有至今的价值、收益差额与收益率</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>生成情绪文案和机会成本对比</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>将复盘结果导出为图片</span></span></code></pre></div><blockquote><p>项目仅用于娱乐和投资复盘，不构成任何投资建议。</p></blockquote><hr><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>技术</th></tr></thead><tbody><tr><td>前端框架</td><td>React 18</td></tr><tr><td>开发语言</td><td>TypeScript</td></tr><tr><td>构建工具</td><td>Vite 5</td></tr><tr><td>行情数据</td><td>东方财富公开行情接口</td></tr><tr><td>图标</td><td>Lucide React</td></tr><tr><td>图片导出</td><td>html2canvas</td></tr><tr><td>样式方案</td><td>React 内联样式、CSS</td></tr></tbody></table><hr><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="股票复盘计算" tabindex="-1">股票复盘计算 <a class="header-anchor" href="#股票复盘计算" aria-label="Permalink to &quot;股票复盘计算&quot;">​</a></h3><p>输入股票代码、卖出数量和卖出价格后，应用会获取股票当前价格，并计算如果一直持有到现在的总价值、收益差额与收益率。</p><h3 id="支持-a-股与美股" tabindex="-1">支持 A 股与美股 <a class="header-anchor" href="#支持-a-股与美股" aria-label="Permalink to &quot;支持 A 股与美股&quot;">​</a></h3><p>项目支持输入 6 位 A 股代码和美股代码，并根据股票市场展示对应的人民币或美元符号。</p><h3 id="今日行情展示" tabindex="-1">今日行情展示 <a class="header-anchor" href="#今日行情展示" aria-label="Permalink to &quot;今日行情展示&quot;">​</a></h3><p>除了复盘结果，页面还会展示当前价格，以及今日开盘价、收盘价、最高价和最低价等行情数据。</p><h3 id="情绪文案" tabindex="-1">情绪文案 <a class="header-anchor" href="#情绪文案" aria-label="Permalink to &quot;情绪文案&quot;">​</a></h3><p>应用会根据收益率区间生成不同级别的情绪文案，让原本偏严肃的收益计算更有趣，也更适合作为复盘结果分享。</p><h3 id="机会成本对比" tabindex="-1">机会成本对比 <a class="header-anchor" href="#机会成本对比" aria-label="Permalink to &quot;机会成本对比&quot;">​</a></h3><p>收益差额会被转换为更容易理解的生活场景，例如可以买多少杯奶茶、多少张电影票、多少台 iPhone，或可以旅行多少天。</p><h3 id="结果图片导出" tabindex="-1">结果图片导出 <a class="header-anchor" href="#结果图片导出" aria-label="Permalink to &quot;结果图片导出&quot;">​</a></h3><p>通过 html2canvas 将复盘结果卡片转换为 PNG 图片，方便保存和分享。</p><hr><h2 id="页面布局" tabindex="-1">页面布局 <a class="header-anchor" href="#页面布局" aria-label="Permalink to &quot;页面布局&quot;">​</a></h2><p>页面采用三列卡片结构，将输入、行情和结果明确分区：</p><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td>左列</td><td>股票代码、卖出数量、卖出价格或日期</td></tr><tr><td>中列</td><td>当前价格与今日行情</td></tr><tr><td>右列</td><td>收益差额、收益率、情绪文案和机会成本</td></tr></tbody></table><p>这种布局让用户可以在同一屏完成输入、查看行情和理解复盘结果。</p><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提交复盘信息</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── 格式化股票代码</span></span>
<span class="line"><span>    ├── 将股票代码转换为东方财富 secid</span></span>
<span class="line"><span>    ├── 请求东方财富当前行情</span></span>
<span class="line"><span>    ├── 请求失败时使用兜底行情</span></span>
<span class="line"><span>    ├── 根据价格、数量计算收益差额</span></span>
<span class="line"><span>    ├── 根据收益率选择情绪文案</span></span>
<span class="line"><span>    ├── 随机选择机会成本对比项</span></span>
<span class="line"><span>    └── 使用 html2canvas 导出结果卡片</span></span></code></pre></div><p>当前版本直接从浏览器请求东方财富公开行情接口，无需额外后端或 CORS 代理：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://push2.eastmoney.com/api/qt/stock/get</span></span></code></pre></div><p>股票代码会先转换成东方财富使用的 <code>secid</code>。例如上交所使用 <code>1.股票代码</code>，深交所使用 <code>0.股票代码</code>，美股则根据交易所使用 <code>105</code>、<code>106</code> 或 <code>107</code>。请求失败或返回数据异常时，部分常见股票会使用内置兜底数据。</p><hr><h2 id="核心计算" tabindex="-1">核心计算 <a class="header-anchor" href="#核心计算" aria-label="Permalink to &quot;核心计算&quot;">​</a></h2><p>假设卖出数量为 <code>quantity</code>，卖出价格为 <code>soldPrice</code>，当前价格为 <code>currentPrice</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当时卖出价值 = quantity × soldPrice</span></span>
<span class="line"><span>持有至今价值 = quantity × currentPrice</span></span>
<span class="line"><span>收益差额 = 持有至今价值 - 当时卖出价值</span></span>
<span class="line"><span>收益率 = 收益差额 ÷ 当时卖出价值 × 100%</span></span></code></pre></div><p>收益差额为正数时，表示错过了一部分上涨收益；为负数时，则说明当时卖出避免了后续亏损。</p><hr><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>If-I-Held/</span></span>
<span class="line"><span>├── assets/</span></span>
<span class="line"><span>│   └── ScreenShot_2026-05-01_003428_494.png</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── App.tsx             # 页面、行情请求与核心计算逻辑</span></span>
<span class="line"><span>│   ├── index.css           # 全局样式</span></span>
<span class="line"><span>│   └── main.tsx            # 应用入口</span></span>
<span class="line"><span>├── index.html</span></span>
<span class="line"><span>├── start.bat               # Windows 一键启动脚本</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>└── vite.config.ts</span></span></code></pre></div><hr><h2 id="本地开发" tabindex="-1">本地开发 <a class="header-anchor" href="#本地开发" aria-label="Permalink to &quot;本地开发&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/xxxeuniii/If-I-Held.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> If-I-Held</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>启动后访问 <code>http://localhost:5123</code>。</p><p>常用命令：</p><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td>启动 Vite 开发服务器</td></tr><tr><td><code>npm run build</code></td><td>执行 TypeScript 检查并构建生产版本</td></tr><tr><td><code>npm run preview</code></td><td>本地预览生产构建</td></tr></tbody></table><p>Windows 用户也可以直接运行项目根目录下的 <code>start.bat</code>。</p><hr><h2 id="项目特点" tabindex="-1">项目特点 <a class="header-anchor" href="#项目特点" aria-label="Permalink to &quot;项目特点&quot;">​</a></h2><ol><li><strong>输入简单直接</strong>：输入股票代码、卖出数量和卖出价格即可完成复盘</li><li><strong>复盘结果直观</strong>：同时展示收益差额、收益率和行情数据</li><li><strong>表达方式有趣</strong>：使用情绪文案和生活消费对比解释机会成本</li><li><strong>支持结果分享</strong>：可以将复盘结果卡片导出为图片</li><li><strong>具备兜底机制</strong>：行情请求失败时仍可使用兜底数据体验功能</li><li><strong>部署简单</strong>：纯前端应用，无需自建后端服务</li></ol><hr><h2 id="当前限制与演进方向" tabindex="-1">当前限制与演进方向 <a class="header-anchor" href="#当前限制与演进方向" aria-label="Permalink to &quot;当前限制与演进方向&quot;">​</a></h2><ul><li>股票代码目前仅支持手动输入，可以增加搜索与自动补全</li><li>东方财富公开接口可能调整、限流或暂时不可用</li><li>可以增加复权价格、手续费、分红和汇率等更完整的计算因素</li><li>可以加入多次买卖记录与持仓组合复盘</li><li>可以增加收益曲线和基准指数对比</li><li>可以将行情请求迁移到自有后端或 Serverless API</li></ul><hr><h2 id="项目链接" tabindex="-1">项目链接 <a class="header-anchor" href="#项目链接" aria-label="Permalink to &quot;项目链接&quot;">​</a></h2><ul><li>在线体验：<a href="https://if-i-held.vercel.app/" target="_blank" rel="noreferrer">https://if-i-held.vercel.app/</a></li><li>GitHub：<a href="https://github.com/xxxeuniii/If-I-Held" target="_blank" rel="noreferrer">xxxeuniii/If-I-Held</a></li><li>License：MIT</li></ul>`,60)])])}const b=s(i,[["render",l]]);export{u as __pageData,b as default};
